from pathlib import Path
import os, json, pickle
import numpy as np
from scipy.io import loadmat
import h5py
files = Path('/tmp/data_files.txt').read_text().strip().splitlines()
print('n_files', len(files))
for f in files[:40]:
    p = Path(f)
    print('\nFILE', f)
    print('size_bytes', p.stat().st_size)
    suf = p.suffix.lower()
    try:
        if suf == '.npy':
            arr = np.load(f, allow_pickle=True)
            print('type', type(arr), 'shape', getattr(arr, 'shape', None), 'dtype', getattr(arr, 'dtype', None))
        elif suf == '.npz':
            z = np.load(f, allow_pickle=True)
            print('npz_keys', list(z.keys())[:20])
        elif suf == '.pkl':
            obj = pickle.load(open(f, 'rb'))
            print('pickle_type', type(obj))
            if isinstance(obj, dict):
                print('dict_keys', list(obj.keys())[:30])
        elif suf == '.mat':
            try:
                m = loadmat(f, simplify_cells=True)
                print('mat_keys', [k for k in m.keys() if not k.startswith('__')][:30])
            except Exception:
                with h5py.File(f, 'r') as h:
                    print('h5_keys', list(h.keys())[:30])
        elif suf in ['.h5', '.hdf5']:
            with h5py.File(f, 'r') as h:
                print('h5_keys', list(h.keys())[:30])
        elif suf in ['.json']:
            obj = json.load(open(f))
            print('json_type', type(obj), 'keys', list(obj)[:20] if isinstance(obj, dict) else None)
        else:
            print('uninspected_suffix', suf)
    except Exception as e:
        print('ERROR', repr(e))
